-- WD.12 (п. 18, власник «Так» 25.11.2026): пакет сценаріїв демо — один проєкт «в межах плану», один «без прогнозу». НЕ ЗАСТОСОВАНО — лише після «так» власника.
-- Нових сутностей немає: змінено три записи останніх звітів ПМа (wr_weekly_snapshots); значення проєктів перерахують тригери archi_recalc_*.
-- 1) DEMO-08 (завершений, 100% по всіх стадіях, акти підписано й оплачено): прибрано «субпідрядник чекає аванс» — для завершеного проєкту це суперечило даним; проєкт стає «в межах плану».
-- 2) DEMO-01 (у роботі): сценарій «субпідрядник блокує» (sub_blocked) переходить сюди з DEMO-08, щоб сценарій лишився в демо.
-- 3) DEMO-09 (у роботі): ПМ не дав ETC по стадії Р (< 100%) → прогноз відсутній (S-01, B-01).
-- Репетиція в транзакції зі скасуванням, live SQL 25.11.2026: DEMO-08 події лише no_report; DEMO-01 події act_due, no_report, sub_blocked; DEMO-09 profit_forecast = NULL, подія no_forecast; прибуток прогноз DEMO-01 203 677 і DEMO-08 205 653 без змін; portfolio: no_forecast 1, sub_blocked 1, решта лічильників без змін.
-- Відкат: sql/2026-11-25_wd12_scenarios_rollback.sql
UPDATE public.wr_weekly_snapshots SET problems = 'Проєкт завершено: усі стадії здано, акти підписано й оплачено. Проблем немає.'
 WHERE id = 264 AND company_id = '00000000-0000-4000-8000-000000000001' AND project_id = 'DEMO-08';
UPDATE public.wr_weekly_snapshots SET problems = 'Невелика затримка погодження з замовником, на терміни не впливає. Субпідрядник по ОВіК не починає роботу, чекає аванс.'
 WHERE id = 256 AND company_id = '00000000-0000-4000-8000-000000000001' AND project_id = 'DEMO-01';
UPDATE public.wr_weekly_snapshots SET "залишок_прогноз_по_стадіях" = "залишок_прогноз_по_стадіях" - 'Р'
 WHERE id = 261 AND company_id = '00000000-0000-4000-8000-000000000001' AND project_id = 'DEMO-09';
